declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\StageDisplayService;Auth::requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid request.');}$roundId=(int)($_POST['round_id']??0);$mode=(string)($_POST['data_mode']??'real');$test=$mode==='test';try{$token=StageDisplayService::generate(Database::connection(),$roundId,$test,(int)(Auth::user()['id']??0));$url=StageDisplayService::publicUrl($token);$return=trim((string)($_POST['return_to']??''));if($return!==''&&str_starts_with($return,'/')){$_SESSION['bdc_stage_display_url']=$url;header('Location: '.$return,true,303);exit;}header('Content-Type: text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stage Display Link</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:900px"><div class="card shadow-sm"><div class="card-body"><h1 class="h4">9:16 Stage / LED Display</h1><p class="text-muted">This URL is read-only presentation access. Generating a new URL does not change competitors, scores or results.</p><div class="input-group"><input id="u" class="form-control" value="<?=e($url)?>" readonly><button class="btn btn-outline-primary" onclick="navigator.clipboard.writeText(document.getElementById('u').value)">Copy</button><a class="btn btn-primary" href="<?=e($url)?>" target="_blank">Open Display</a></div></div></div></main></body></html><?php }catch(Throwable $e){http_response_code(422);exit(e($e->getMessage()));}